      id.hashCode ^
      name.hashCode ^
      author.hashCode ^
      license.hashCode ^
      source.hashCode ^
      dark.hashCode ^
      origin.hashCode ^
      tokens.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ThemeRow &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          name == other.name &&
          author == other.author &&
          license == other.license &&
          source == other.source &&
          dark == other.dark &&
          origin == other.origin &&
          tokens == other.tokens;
}

class ThemeTokens {
  final String name;
  final bool dark;
  final List<ColorRow> ui;
  final int caret;
  final int selection;
  final int selectionAlpha;
  final List<SyntaxStyleRow> syntax;
  final PaletteDto palette;

  const ThemeTokens({
    required this.name,
    required this.dark,
    required this.ui,
    required this.caret,
    required this.selection,
    required this.selectionAlpha,
    required this.syntax,
    required this.palette,
  });

  @override
  int get hashCode =>
      name.hashCode ^
      dark.hashCode ^
      ui.hashCode ^
      caret.hashCode ^
      selection.hashCode ^
      selectionAlpha.hashCode ^
      syntax.hashCode ^
      palette.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ThemeTokens &&
          runtimeType == other.runtimeType &&
          name == other.name &&
          dark == other.dark &&
          ui == other.ui &&
          caret == other.caret &&
          selection == other.selection &&
          selectionAlpha == other.selectionAlpha &&
          syntax == other.syntax &&
          palette == other.palette;
}
